import math

class RotationalSensors:
  def __init__(self):
    self.angle = 0

  def read(self, num_iterations):
    angle_sum = 0
    for _ in range(num_iterations):
      angle_sum += self.get_angle()
      angle_sum += math.pi / 2
    average = angle_sum / num_iterations
    return average

  def get_angle(self, num_rotations):
    return num_rotations * 2 * math.pi

